=== calendar/index.html ===
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta http-equiv="Content-Security-Policy"
      content="default-src 'self'; script-src 'self'; connect-src 'self' https://api.github.com">
<title>Calendar</title>
<link rel="apple-touch-icon" href="icon.svg">
<meta name="theme-color" content="#1f2933">
<link rel="stylesheet" href="../style.css">
<link rel="stylesheet" href="style.css">
</head>
<body>

<section id="needs-setup" hidden>
  <header><h1>Calendar</h1><a class="icon-btn" href="../">✕</a></header>
  <p class="lede">Mine is not set up on this device yet.</p>
  <p><a href="../">Open Mine</a> and enter the repo and token once; the calendar then uses them.</p>
</section>

<main id="cal" hidden>
  <div class="topbar">
    <button id="prev" class="nav" aria-label="Previous">‹</button>
    <button id="next" class="nav" aria-label="Next">›</button>
    <button id="period" class="period" aria-haspopup="true" aria-expanded="false">
      <span id="period-label">—</span><span class="caret">▾</span>
    </button>
    <span class="spacer"></span>
    <button id="today" class="nav wide">Today</button>
    <button id="add" class="nav ic" aria-label="Add an entry"><svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" d="M8 3v10M3 8h10"/></svg></button>
    <button id="filter-btn" class="nav ic" aria-label="Filter" aria-haspopup="true" aria-expanded="false"><svg viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" d="M2 3h12l-4.8 5.8V14L6.8 12.6V8.8z"/></svg></button>
    <div class="modes" role="radiogroup" aria-label="View">
      <button class="mode" data-mode="D" aria-pressed="false" aria-label="Day">D</button>
      <button class="mode" data-mode="W" aria-pressed="false" aria-label="Week">W</button>
      <button class="mode" data-mode="M" aria-pressed="true" aria-label="Month">M</button>
      <button class="mode" data-mode="Y" aria-pressed="false" aria-label="Year">Y</button>
      <button class="mode" data-mode="K" aria-pressed="false" aria-label="Kanban">K</button>
    </div>
    <a class="nav" href="../" aria-label="Back to Mine">←</a>
    <button id="gear" class="nav" aria-label="Settings">⚙</button>
  </div>

  <div class="view" id="view"></div>
  <p class="sync" id="sync"></p>
</main>

<!-- dropdown date picker: a month at a time, a 9-year grid, or a list of sprints -->
<div class="pop" id="picker" hidden>
  <div class="pop-head">
    <button id="pick-title" class="pop-title" type="button"><span id="pick-label">—</span></button>
    <span class="spacer"></span>
    <button id="pick-prev" class="nav" type="button" aria-label="Previous">‹</button>
    <button id="pick-next" class="nav" type="button" aria-label="Next">›</button>
  </div>
  <div class="pick-body" id="pick-body"></div>
</div>

<!-- view filter: groups always, priority and assignee on the board -->
<div class="pop" id="filter-pop" hidden>
  <div id="filter-body"></div>
</div>

<!-- the day preview: a list on desktop, a sheet on a phone -->
<div class="pop" id="day-pop" hidden>
  <div class="pop-head">
    <strong id="day-title">—</strong><span class="spacer"></span>
    <button class="ib" id="day-add" type="button" title="Add an entry on this day" aria-label="Add an entry on this day"><svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" d="M8 3v10M3 8h10"/></svg></button>
    <button class="ib" id="day-close" type="button" title="Close" aria-label="Close"><svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" d="M4 4l8 8M12 4l-8 8"/></svg></button>
  </div>
